/// The velocities the three dynamics were measured at (pp, mf, ff).
const AT: [f32; 3] = [0.26, 0.62, 0.87];

/// A bowed string's body (one instrument's resonances add a ripple).
pub fn is_string(body: u8) -> bool {
    body < 4
}

fn knot(curve: &[f32; KNOTS], hz: f32) -> f32 {
    let x = ((hz.max(1.0) / KNOT0).log2() * PER_OCTAVE).clamp(0.0, (KNOTS - 1) as f32);
    let i = (x as usize).min(KNOTS - 2);
    let t = x - i as f32;
    curve[i] * (1.0 - t) + curve[i + 1] * t
}

/// The level (dB, 0 at 1 kHz) of an odd or even harmonic at `hz` on a
/// body, at dynamic `d` (0..1): between the measured dynamics, a little
/// beyond them.
pub fn level(body: u8, hz: f32, d: f32, even: bool) -> f32 {
    let c = &BODY[body as usize];
    let (a, b, t) = if d < AT[1] { (0, 1, (d - AT[0]) / (AT[1] - AT[0])) } else { (1, 2, (d - AT[1]) / (AT[2] - AT[1])) };
    let t = t.clamp(-0.5, 1.5);
    let p = even as usize;
    let (la, lb) = (knot(&c[a][p], hz), knot(&c[b][p], hz));
    la + (lb - la) * t
}

/// A section's body: many instruments, their resonances averaged (a third
/// of an octave).
pub fn section_level(body: u8, hz: f32, d: f32, even: bool) -> f32 {
    let k = 2f32.powf(1.0 / 6.0);
    (level(body, hz / k, d, even) + level(body, hz, d, even) + level(body, hz * k, d, even)) / 3.0
}

/// One string instrument's own resonances over the measured average: fixed
/// peaks and dips of a few dB between 250 Hz and 6 kHz, the same every
/// time (an instrument does not change), different for each body. Winds
/// and brass have none (their tubes, not a wooden box, shape the sound).
pub fn ripple(body: u8, hz: f32) -> f32 {
    if !is_string(body) || !(200.0..7000.0).contains(&hz) {
        return 0.0;
    }
    let o = hz.log2();
    let s = body as f32 * 1.7;
    let w = ((o - 7.64) / 0.5).clamp(0.0, 1.0) * ((12.77 - o) / 0.5).clamp(0.0, 1.0);
    w * (2.2 * (std::f32::consts::TAU * o / 0.17 + s).sin() + 1.4 * (std::f32::consts::TAU * o / 0.29 + 2.3 * s).sin() + 0.8 * (std::f32::consts::TAU * o / 0.11 + 0.7 * s).sin())
}

/// A curve at fine resolution, as linear gains: a forty-eighth of an
/// octave from [`KNOT0`] up, for quick lookups by harmonic.
pub const FINE_PER_OCTAVE: f32 = 48.0;
pub const FINE: usize = 410;

/// The gains of `body` at dynamic `d` for odd and even harmonics, a
/// section's (averaged) or one instrument's (with its ripple); `shape(hz)`:
/// extra dB (a technique, a mute).
pub fn fine_curves(body: u8, d: f32, section: bool, shape: impl Fn(f32) -> f32, odd: &mut [f32; FINE], even: &mut [f32; FINE]) {
    for i in 0..FINE {
        let hz = KNOT0 * 2f32.powf(i as f32 / FINE_PER_OCTAVE);
        let extra = shape(hz) + if section { 0.0 } else { ripple(body, hz) };
        let l = |e: bool| if section { section_level(body, hz, d, e) } else { level(body, hz, d, e) };
        odd[i] = 10f32.powf((l(false) + extra) / 20.0);
        even[i] = 10f32.powf((l(true) + extra) / 20.0);
    }
}

/// The gain at `hz` (as log2) from a fine curve.
#[inline]
pub fn at(curve: &[f32; FINE], log2_hz: f32) -> f32 {
    let x = ((log2_hz - KNOT0.log2()) * FINE_PER_OCTAVE).clamp(0.0, (FINE - 1) as f32);
    let i = (x as usize).min(FINE - 2);
    let t = x - i as f32;
    curve[i] + (curve[i + 1] - curve[i]) * t
}

/// The dynamics the curves are made ready at: 0, 1/8 .. 1.
pub const LEVELS: usize = 9;

/// A body's curves, ready: [dynamic level][odd, even], a soloist's (with
/// the instrument's ripple) and a section's, made once (the main thread,
/// when the plugin is made), so that a note only blends two of them.
pub type Ready = [[[f32; FINE]; 2]; LEVELS];

pub fn ready(body: u8, section: bool) -> &'static Ready {
    static READY: std::sync::OnceLock<Vec<Box<Ready>>> = std::sync::OnceLock::new();
    let all = READY.get_or_init(|| {
        let mut v = Vec::with_capacity(BODIES * 2);
        for b in 0..BODIES as u8 {
            for s in [false, true] {
                let mut r: Box<Ready> = Box::new([[[0.0; FINE]; 2]; LEVELS]);
                for (l, level) in r.iter_mut().enumerate() {
                    let (odd, even) = level.split_at_mut(1);
                    fine_curves(b, l as f32 / (LEVELS - 1) as f32, s, |_| 0.0, &mut odd[0], &mut even[0]);
                }
                v.push(r);
            }
        }
        v
    });
    &all[body as usize * 2 + section as usize]
}

/// A body's curves at dynamic `d`, blended from the ready ones.
pub fn blend(body: u8, d: f32, section: bool, odd: &mut [f32; FINE], even: &mut [f32; FINE]) {
    let r = ready(body, section);
    let x = (d.clamp(0.0, 1.0) * (LEVELS - 1) as f32).min((LEVELS - 1) as f32 - 1e-4);
    let i = x as usize;
    let t = x - i as f32;
    for k in 0..FINE {
        odd[k] = r[i][0][k] + (r[i + 1][0][k] - r[i][0][k]) * t;
        even[k] = r[i][1][k] + (r[i + 1][1][k] - r[i][1][k]) * t;
    }
}
